    static int[][] f2 = new int[MAXN][MAXN];
    static int[] g1 = new int[MAXN];
    static int[][] g2 = new int[MAXN][MAXN];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        P = sc.nextInt();

        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P;
            }
        }

        f1[0] = 1;
        for (int i = 1; i <= n; i++) {
            f1[i] = 0;
            g1[i] = 0;
            for (int j = 1; j <= i; j++) {
                long temp1 = ((long)f1[j - 1] * f1[i - j]) % P;
                long temp2 = ((long)f1[j - 1] * g1[i - j] + (long)g1[j - 1] * f1[i - j]) % P;
                f1[i] = (int)((f1[i] + temp1 * C[i - 1][j - 1]) % P);
                int t = (int)((temp2 * (long)(i + 1)) % P);
                long g1_add = ((long)f1[j - 1] * f1[i - j]) % P;
                g1_add = (g1_add * (C[j][2] + C[i - j + 1][2])) % P;
                g1_add = (g1_add + t) % P;
                g1[i] = (int)((g1[i] + g1_add * C[i - 1][j - 1]) % P);
            }
            f1[i] = (int)(((long)(i + 1) * f1[i]) % P);
        }

        g2[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= Math.min(i, m); j++) {
                f2[i][j] = f2[i - 1][j];
                g2[i][j] = g2[i - 1][j];
                for (int k = 1; k <= j; k++) {
                    long f_val = (i - k != 0) ? f2[i - k - 1][j - k] : 1;
                    f2[i][j] = (int)((f2[i][j] + f_val * (long)f1[k] % P * C[j][k]) % P);
                    long g_val = (i - k != 0) ? f2[i - k - 1][j - k] : 1;
                    long g_part = ((g_val * g1[k]) + ((i - k != 0) ? g2[i - k - 1][j - k] : 0) * f1[k]) % P;
                    g2[i][j] = (int)((g2[i][j] + g_part * C[j][k]) % P);
                }
            }
        }

        System.out.println(g2[n][m]);
        sc.close();
    }
}
